// Webhook de Alertmanager: decide la acción por alerta (SAD 2.14: drift → reentrenamiento).
return ($json.body.alerts || []).map((a) => {
  const nombre = a.labels.alertname;
  let accion = `Notificar al equipo de ${a.labels.equipo || 'plataforma'}`;
  if (a.status === 'firing' && nombre === 'DriftDeModelo') {
    accion = `Abrir solicitud de reentrenamiento del modelo ${a.labels.modelo}: informe Evidently + `
           + 'pipeline de ML (producción: workflow_dispatch de GitHub Actions)';
  }
  if (a.status === 'firing' && a.labels.severidad === 'critica') accion += ' · avisar a la guardia';
  if (a.status === 'resolved') accion = 'Cerrar el incidente';
  return { json: { alerta: nombre, estado: a.status, severidad: a.labels.severidad,
                   resumen: a.annotations.resumen, recomendacion: a.annotations.accion, accion } };
});
